import React, { useState } from 'react';

const Dashboard = ({ onNavigate }) => {
  const [pnrInput, setPnrInput] = useState('');
  const [flights, setFlights] = useState([
    { flight: 'AI-202', to: 'Hyderabad (HYD)', departs: '10:30 AM', gate: 'T3-A12', status: 'BOARDING' },
    { flight: '6E-501', to: 'Vijayawada (VGA)', departs: '02:30 PM', gate: 'T1-04', status: 'ON-TIME' },
    { flight: 'UK-943', to: 'Mumbai (BOM)', departs: '04:15 PM', gate: 'T3-B02', status: 'ON-TIME' },
  ]);

  const handleTrack = async () => {
    try {
      const response = await fetch(`http://localhost:5000/get-pnr/${pnrInput.toUpperCase()}`);
      if (response.ok) {
        const data = await response.json();
        // Add tracked flight to the list or show alert
        setFlights([data, ...flights]);
        alert(`Flight Found: ${data.flight} to ${data.to}. Status: ${data.status}`);
      } else { alert("PNR not found in SkySync records."); }
    } catch (err) { alert("Server error."); }
  };

  const handleVoiceCall = async () => {
    const res = await fetch('http://localhost:5000/make-call', { method: 'POST' });
    const data = await res.json();
    if (data.success) alert("Calling now...");
  };

  return (
    <div style={{ background: '#f8fafc', height: '100vh', display: 'flex', fontFamily: 'Inter, sans-serif' }}>
      <div style={{ width: '260px', background: '#0a1931', color: '#cbd5e1', padding: '25px', display: 'flex', flexDirection: 'column' }}>
        <b style={{ color: '#fbbf24', fontSize: '20px', marginBottom: '35px' }}>✈️ SkySync</b>
        <button onClick={handleVoiceCall} style={{ background: '#1d4ed8', color: 'white', border: 'none', padding: '14px', borderRadius: '8px', cursor: 'pointer', marginBottom: '10px', fontWeight: 'bold' }}>📞 Start Voice Call</button>
        <button onClick={() => onNavigate('voiceweb')} style={{ background: '#10b981', color: 'white', border: 'none', padding: '14px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>🌐 Start Voice Web</button>
      </div>

      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflowY: 'auto' }}>
        <div style={{ background: '#1d4ed8', color: 'white', padding: '50px 60px', textAlign: 'center' }}>
          <h1>Welcome to SkySync</h1>
          <div style={{ display: 'flex', gap: '10px', background: 'white', padding: '8px', borderRadius: '12px', maxWidth: '550px', margin: '0 auto' }}>
            <input value={pnrInput} onChange={(e) => setPnrInput(e.target.value)} type="text" placeholder="Enter PNR (e.g., SKY1234)" style={{ flex: 1, padding: '12px', border: 'none', outline: 'none', color: '#333' }} />
            <button onClick={handleTrack} style={{ background: '#059669', color: 'white', border: 'none', padding: '0 25px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Track Flight</button>
          </div>
        </div>

        <div style={{ padding: '40px 60px' }}>
          <b style={{ color: '#0a1931', fontSize: '18px' }}>Live Departures</b>
          <table style={{ width: '100%', borderCollapse: 'collapse', background: 'white', marginTop: '20px', border: '1px solid #e2e8f0' }}>
            <thead style={{ background: '#f1f5f9', textAlign: 'left', fontSize: '10px' }}>
              <tr><th style={{ padding: '18px' }}>Flight</th><th style={{ padding: '18px' }}>To</th><th style={{ padding: '18px' }}>Departs</th><th style={{ padding: '18px' }}>Status</th></tr>
            </thead>
            <tbody>
              {flights.map((f, i) => (
                <tr key={i} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '13px' }}>
                  <td style={{ padding: '18px', fontWeight: 'bold' }}>{f.flight}</td>
                  <td style={{ padding: '18px' }}>{f.to}</td>
                  <td style={{ padding: '18px' }}>{f.departs}</td>
                  <td style={{ padding: '18px' }}><span style={{ background: '#dcfce7', color: '#15803d', padding: '5px 10px', borderRadius: '20px' }}>{f.status}</span></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
